    theoryBreakdown: 'Differential Calculus begins with the concept of a Limit: the value a function approaches as the input approaches some target value. The First Principle of Derivative defines instantaneous rate of change: f’(x) = lim_{h→0} [f(x+h) - f(x)]/h. Geometrically, (x, f(x)) and (x+h, f(x+h)) form a secant line with average slope Δy/Δx. As h → 0, the secant line rotates and converges to the unique tangent line touching the curve at (x, f(x)). The Squeeze Theorem bounds sin(x)/x between cos(x) and 1 on the unit circle, proving lim_{x→0} sin(x)/x = 1.',
