    theoryBreakdown: 'Fundamental Principle of Counting states that if task A can be done in m ways and task B in n ways, both can be done in m × n ways. (1) Permutation: an ordered arrangement of r objects from n distinct objects: ⁿPᵣ = n! / (n-r)!. Order matters: [A, B] ≠ [B, A]. (2) Combination: an unordered selection of r objects from n distinct objects: ⁿCᵣ = n! / [r!(n-r)!]. Each combination group of r items has r! identical orderings, which are divided out: ⁿCᵣ = ⁿPᵣ / r!. (3) Circular Permutation: arranging n objects in a circle has (n-1)! ways because rotating the circle produces identical relative configurations.',
