    theoryBreakdown: "Bayes' Theorem updates the probability of an event (hypothesis A) based on new evidence (event B): (1) Prior Probability P(A): the initial baseline belief before any test is performed (the base rate). (2) Likelihood P(B|A): the probability of observing the evidence given that the hypothesis is true (test sensitivity). (3) Law of Total Probability: P(B) = P(B|A)·P(A) + P(B|A′)·P(A′), which accounts for evidence coming from both true cases and false alarms. (4) Posterior Probability P(A|B): the updated belief after observing evidence: P(A|B) = [P(B|A)·P(A)] / P(B). When a condition is rare (P(A) << 1), even an accurate test produces many false positives.",
