    theoryBreakdown: 'In 3D Euclidean space, two lines can be: (1) Parallel: direction vectors are scalar multiples (b₁ = k·b₂). (2) Intersecting: they lie in a common plane and meet at a single point (shortest distance d = 0). (3) Skew: they are neither parallel nor intersecting and lie in different planes! The shortest distance between two skew lines L₁: r = a₁ + λb₁ and L₂: r = a₂ + μb₂ is along the line perpendicular to BOTH lines. Since the common perpendicular is orthogonal to b₁ and b₂, its direction is along the unit normal n = (b₁ × b₂) / |b₁ × b₂|. The shortest distance d is the projection of the vector (a₂ - a₁) onto n: d = |(a₂ - a₁) · n|.',
